/*!
 * ApexCharts Offline Bundle for AU Notes HTML Artifacts & Visual Engine
 * Supports: line, area, bar, column, pie, donut, radar, radialBar, scatter
 * Features: Smooth bezier curves, SVG gradients, interactive tooltips, responsive layout, PNG/SVG export
 */
(function (global) {
  "use strict";

  var DEFAULT_PALETTE_LIGHT = [
    "#EA580C", "#2563EB", "#16A34A", "#9333EA", "#DC2626", "#CA8A04", "#0D9488", "#4F46E5"
  ];
  var DEFAULT_PALETTE_DARK = [
    "#FB923C", "#60A5FA", "#4ADE80", "#C084FC", "#F87171", "#FACC15", "#2DD4BF", "#818CF8"
  ];

  function isObject(v) {
    return v !== null && typeof v === "object" && !Array.isArray(v);
  }

  function deepMerge(target, source) {
    var out = Object.assign({}, target);
    if (!isObject(source)) return out;
    Object.keys(source).forEach(function (k) {
      if (isObject(source[k]) && isObject(out[k])) {
        out[k] = deepMerge(out[k], source[k]);
      } else if (source[k] !== undefined) {
        out[k] = source[k];
      }
    });
    return out;
  }

  function formatNumber(n, unit) {
    if (n === null || n === undefined || isNaN(n)) return "0";
    var num = Number(n);
    var abs = Math.abs(num);
    var formatted;
    if (abs >= 1e9) formatted = (num / 1e9).toFixed(1).replace(/\.0$/, "") + "B";
    else if (abs >= 1e6) formatted = (num / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
    else if (abs >= 1e4) formatted = (num / 1e3).toFixed(1).replace(/\.0$/, "") + "K";
    else if (Math.floor(num) === num) formatted = String(num);
    else formatted = num.toFixed(2).replace(/\.?0+$/, "");
    return unit ? formatted + (unit === "%" ? "%" : " " + unit) : formatted;
  }

  function escapeXml(str) {
    return String(str == null ? "" : str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function normalizeOptions(raw) {
    if (!isObject(raw)) throw new Error("Invalid ApexCharts configuration object");
    var chartType = (
      (raw.chart && raw.chart.type) ||
      raw.type ||
      raw.chart_type ||
      "bar"
    ).toString().toLowerCase().trim();

    if (chartType === "column") chartType = "bar";
    if (chartType === "doughnut") chartType = "donut";

    var isDark =
      (raw.theme && raw.theme.mode === "dark") ||
      document.documentElement.getAttribute("data-theme") === "dark" ||
      document.body.classList.contains("dark");

    var palette = (Array.isArray(raw.colors) && raw.colors.length > 0)
      ? raw.colors
      : (isDark ? DEFAULT_PALETTE_DARK : DEFAULT_PALETTE_LIGHT);

    var titleText = "";
    if (typeof raw.title === "string") titleText = raw.title;
    else if (raw.title && typeof raw.title.text === "string") titleText = raw.title.text;

    var subtitleText = "";
    if (typeof raw.subtitle === "string") subtitleText = raw.subtitle;
    else if (raw.subtitle && typeof raw.subtitle.text === "string") subtitleText = raw.subtitle.text;

    var unit = raw.unit || (raw.yaxis && raw.yaxis.unit) || "";

    var categories = [];
    if (Array.isArray(raw.categories)) categories = raw.categories.slice();
    else if (raw.xaxis && Array.isArray(raw.xaxis.categories)) categories = raw.xaxis.categories.slice();
    else if (Array.isArray(raw.labels)) categories = raw.labels.slice();

    var rawSeries = raw.series;
    if (!Array.isArray(rawSeries) && Array.isArray(raw.items)) {
      // Support legacy items array: [{label, value}]
      categories = raw.items.map(function (it, i) { return it.label || ("Item " + (i + 1)); });
      rawSeries = [{
        name: titleText || "Value",
        data: raw.items.map(function (it) { return Number(it.value) || 0; })
      }];
    } else if (!Array.isArray(rawSeries) && Array.isArray(raw.data)) {
      rawSeries = [{ name: titleText || "Series 1", data: raw.data }];
    }

    if (!Array.isArray(rawSeries) || rawSeries.length === 0) {
      throw new Error("Series data is missing or empty");
    }

    var series = [];
    var isPieLike = chartType === "pie" || chartType === "donut" || chartType === "radialbar";

    if (isPieLike && typeof rawSeries[0] === "number") {
      series = [{
        name: titleText || "Share",
        data: rawSeries.map(function (v) { return Number(v) || 0; })
      }];
    } else {
      series = rawSeries.map(function (s, idx) {
        if (typeof s === "number") {
          return { name: "Series " + (idx + 1), data: [Number(s) || 0] };
        }
        if (isObject(s) && Array.isArray(s.data)) {
          var extractedCats = [];
          var nums = s.data.map(function (pt, pIdx) {
            if (typeof pt === "number") return isNaN(pt) ? 0 : pt;
            if (isObject(pt)) {
              if (pt.x !== undefined) extractedCats[pIdx] = String(pt.x);
              else if (pt.label !== undefined) extractedCats[pIdx] = String(pt.label);
              return Number(pt.y !== undefined ? pt.y : pt.value) || 0;
            }
            return Number(pt) || 0;
          });
          if (categories.length === 0 && extractedCats.length > 0) {
            categories = extractedCats;
          }
          return {
            name: s.name || ("Series " + (idx + 1)),
            data: nums,
            color: s.color || palette[idx % palette.length]
          };
        }
        if (isObject(s) && typeof s.value === "number") {
          categories.push(s.label || s.name || ("Item " + (idx + 1)));
          return { name: s.label || ("Item " + (idx + 1)), data: [Number(s.value) || 0] };
        }
        return { name: "Series " + (idx + 1), data: [] };
      });
    }

    // Consolidate single-value object series [{name, data:[v]}, ...] into one series if appropriate
    if (!isPieLike && series.length > 1 && series.every(function (s) { return s.data.length === 1; }) && categories.length === series.length) {
      series = [{
        name: titleText || "Values",
        data: series.map(function (s) { return s.data[0]; })
      }];
    }

    var maxLen = 0;
    series.forEach(function (s) {
      if (s.data.length > maxLen) maxLen = s.data.length;
    });
    if (maxLen === 0) throw new Error("No numeric data points in series");

    while (categories.length < maxLen) {
      categories.push("Item " + (categories.length + 1));
    }

    var horizontal = !!(raw.plotOptions && raw.plotOptions.bar && raw.plotOptions.bar.horizontal);

    return {
      type: chartType,
      isDark: isDark,
      palette: palette,
      title: titleText,
      subtitle: subtitleText,
      unit: unit,
      categories: categories,
      series: series,
      horizontal: horizontal,
      height: (raw.chart && Number(raw.chart.height)) || Number(raw.height) || 340
    };
  }

  function buildSmoothPath(points) {
    if (!points || points.length === 0) return "";
    if (points.length === 1) return "M " + points[0].x.toFixed(1) + " " + points[0].y.toFixed(1);
    var d = "M " + points[0].x.toFixed(1) + " " + points[0].y.toFixed(1);
    for (var i = 0; i < points.length - 1; i++) {
      var p0 = points[i === 0 ? 0 : i - 1];
      var p1 = points[i];
      var p2 = points[i + 1];
      var p3 = points[i + 2 < points.length ? i + 2 : i + 1];
      var cp1x = p1.x + (p2.x - p0.x) / 6;
      var cp1y = p1.y + (p2.y - p0.y) / 6;
      var cp2x = p2.x - (p3.x - p1.x) / 6;
      var cp2y = p2.y - (p3.y - p1.y) / 6;
      d += " C " + cp1x.toFixed(1) + " " + cp1y.toFixed(1) + ", " +
           cp2x.toFixed(1) + " " + cp2y.toFixed(1) + ", " +
           p2.x.toFixed(1) + " " + p2.y.toFixed(1);
    }
    return d;
  }

  function ApexCharts(el, options) {
    this.el = typeof el === "string" ? document.querySelector(el) : el;
    this.rawOptions = options || {};
    this.uid = "apex_" + Math.random().toString(36).substring(2, 9);
    this.svgElement = null;
  }

  ApexCharts.prototype.render = function () {
    var self = this;
    return new Promise(function (resolve, reject) {
      try {
        if (!self.el) throw new Error("Target container not found");
        var cfg = normalizeOptions(self.rawOptions);
        self._draw(cfg);
        resolve(self);
      } catch (err) {
        if (self.el) {
          self.el.innerHTML =
            '<div class="au-chart-error" style="padding:20px;border-radius:14px;border:1.5px dashed #EF4444;background:rgba(239,68,68,0.08);color:#EF4444;font-family:system-ui,sans-serif;font-size:13px;text-align:center;font-weight:600;">' +
            'Chart could not be generated' +
            '</div>';
        }
        resolve(self);
      }
    });
  };

  ApexCharts.prototype.updateOptions = function (newOpts) {
    this.rawOptions = deepMerge(this.rawOptions, newOpts || {});
    return this.render();
  };

  ApexCharts.prototype.destroy = function () {
    if (this.el) this.el.innerHTML = "";
  };

  ApexCharts.prototype.getSvgString = function () {
    if (!this.el) return "";
    var svg = this.el.querySelector("svg");
    if (!svg) return "";
    var clone = svg.cloneNode(true);
    clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
    return new XMLSerializer().serializeToString(clone);
  };

  ApexCharts.prototype.dataURI = function () {
    var self = this;
    return new Promise(function (resolve) {
      var svgStr = self.getSvgString();
      if (!svgStr) {
        resolve({ imgURI: "" });
        return;
      }
      var svgBlob = new Blob([svgStr], { type: "image/svg+xml;charset=utf-8" });
      var url = URL.createObjectURL(svgBlob);
      var img = new Image();
      img.onload = function () {
        var canvas = document.createElement("canvas");
        canvas.width = img.width * 2 || 1200;
        canvas.height = img.height * 2 || 720;
        var ctx = canvas.getContext("2d");
        ctx.fillStyle = self._lastCfg && self._lastCfg.isDark ? "#141418" : "#FAF8F5";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        URL.revokeObjectURL(url);
        resolve({ imgURI: canvas.toDataURL("image/png") });
      };
      img.onerror = function () {
        URL.revokeObjectURL(url);
        resolve({ imgURI: "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgStr))) });
      };
      img.src = url;
    });
  };

  ApexCharts.prototype._draw = function (cfg) {
    this._lastCfg = cfg;
    var isDark = cfg.isDark;
    var textPrimary = isDark ? "#F4F4F6" : "#18181B";
    var textMuted = isDark ? "#A1A1AA" : "#64748B";
    var gridColor = isDark ? "rgba(255,255,255,0.09)" : "rgba(24,24,27,0.09)";
    var cardBg = isDark ? "#18181E" : "#FFFFFF";

    var W = 680;
    var H = Math.max(280, Math.min(460, cfg.height));
    var svgParts = [];
    var defs = [];

    // Palette gradients
    cfg.palette.forEach(function (col, i) {
      var gid = this.uid + "_grad_" + i;
      defs.push(
        '<linearGradient id="' + gid + '" x1="0" y1="0" x2="0" y2="1">' +
          '<stop offset="0%" stop-color="' + escapeXml(col) + '" stop-opacity="0.52"/>' +
          '<stop offset="95%" stop-color="' + escapeXml(col) + '" stop-opacity="0.03"/>' +
        '</linearGradient>'
      );
      var bgid = this.uid + "_bargrad_" + i;
      defs.push(
        '<linearGradient id="' + bgid + '" x1="0" y1="0" x2="0" y2="1">' +
          '<stop offset="0%" stop-color="' + escapeXml(col) + '" stop-opacity="1"/>' +
          '<stop offset="100%" stop-color="' + escapeXml(col) + '" stop-opacity="0.82"/>' +
        '</linearGradient>'
      );
    }, this);

    var headerOffset = 18;
    if (cfg.title) {
      svgParts.push(
        '<text x="20" y="28" fill="' + textPrimary + '" font-family="system-ui,-apple-system,sans-serif" font-size="16" font-weight="800">' +
        escapeXml(cfg.title) + '</text>'
      );
      headerOffset = 40;
    }
    if (cfg.subtitle) {
      svgParts.push(
        '<text x="20" y="' + (headerOffset + 6) + '" fill="' + textMuted + '" font-family="system-ui,-apple-system,sans-serif" font-size="12" font-weight="500">' +
        escapeXml(cfg.subtitle) + '</text>'
      );
      headerOffset += 20;
    }

    if (cfg.type === "pie" || cfg.type === "donut" || cfg.type === "radialbar") {
      this._drawPieDonut(cfg, svgParts, W, H, headerOffset, textPrimary, textMuted, cardBg);
    } else if (cfg.type === "radar") {
      this._drawRadar(cfg, svgParts, W, H, headerOffset, textPrimary, textMuted, gridColor);
    } else {
      this._drawCartesian(cfg, svgParts, W, H, headerOffset, textPrimary, textMuted, gridColor, cardBg);
    }

    var svgHtml =
      '<div class="apexcharts-canvas" style="position:relative;width:100%;user-select:none;">' +
        '<svg viewBox="0 0 ' + W + ' ' + H + '" style="width:100%;height:auto;display:block;overflow:visible;" xmlns="http://www.w3.org/2000/svg">' +
          '<defs>' + defs.join("") + '</defs>' +
          svgParts.join("") +
        '</svg>' +
        '<div class="apex-tooltip" style="position:absolute;pointer-events:none;opacity:0;transition:opacity 0.14s ease,transform 0.14s ease;background:' + (isDark ? "#27272A" : "#18181B") + ';color:#FFFFFF;padding:8px 12px;border-radius:10px;font-family:system-ui,-apple-system,sans-serif;font-size:12px;box-shadow:0 8px 24px rgba(0,0,0,0.25);z-index:20;white-space:nowrap;"></div>' +
      '</div>';

    this.el.innerHTML = svgHtml;
    this._bindInteractions();
  };

  ApexCharts.prototype._drawCartesian = function (cfg, svgParts, W, H, topStart, textPrimary, textMuted, gridColor, cardBg) {
    var allVals = [];
    cfg.series.forEach(function (s) {
      s.data.forEach(function (v) { allVals.push(Number(v) || 0); });
    });
    var minVal = Math.min.apply(null, allVals.concat([0]));
    var maxVal = Math.max.apply(null, allVals.concat([1]));
    if (maxVal === minVal) maxVal = minVal + 10;

    // Calculate nice Y-axis bounds
    var span = maxVal - minVal;
    var rawStep = span / 4;
    var mag = Math.pow(10, Math.floor(Math.log10(Math.max(rawStep, 1e-6))));
    var normStep = rawStep / mag;
    var step = (normStep <= 1 ? 1 : normStep <= 2 ? 2 : normStep <= 2.5 ? 2.5 : normStep <= 5 ? 5 : 10) * mag;
    var niceMin = minVal < 0 ? Math.floor(minVal / step) * step : 0;
    var niceMax = Math.ceil(maxVal / step) * step;
    if (niceMax <= niceMin) niceMax = niceMin + step * 4;

    var ticks = [];
    for (var tv = niceMin; tv <= niceMax + step * 0.001; tv += step) {
      ticks.push(tv);
      if (ticks.length > 7) break;
    }

    // Measure longest Y-axis label so it never overlaps plot area
    var maxYLabelChars = 0;
    ticks.forEach(function (t) {
      var lbl = formatNumber(t, cfg.unit);
      if (lbl.length > maxYLabelChars) maxYLabelChars = lbl.length;
    });

    var hasLegend = cfg.series.length > 1;
    var legendH = hasLegend ? 28 : 6;
    var maxCatChars = 0;
    cfg.categories.forEach(function (c) {
      var len = String(c).length;
      if (len > maxCatChars) maxCatChars = len;
    });
    var rotateX = cfg.categories.length > 6 || maxCatChars > 10;
    var bottomPad = (rotateX ? 62 : 40) + legendH;
    var leftPad = Math.max(54, Math.min(115, maxYLabelChars * 7.8 + 20));
    var rightPad = 24;
    var plotTop = topStart + 16;
    var plotH = Math.max(120, H - plotTop - bottomPad);
    var plotW = W - leftPad - rightPad;

    // Horizontal grid lines & Y labels
    ticks.forEach(function (t) {
      var ratio = (t - niceMin) / (niceMax - niceMin);
      var y = plotTop + plotH * (1 - ratio);
      var isZero = Math.abs(t) < 1e-9;
      svgParts.push(
        '<line x1="' + leftPad + '" y1="' + y.toFixed(1) + '" x2="' + (leftPad + plotW) + '" y2="' + y.toFixed(1) + '" ' +
        'stroke="' + gridColor + '" stroke-width="' + (isZero ? "1.6" : "1") + '" ' +
        (isZero ? '' : 'stroke-dasharray="4 4"') + '/>'
      );
      svgParts.push(
        '<text x="' + (leftPad - 10) + '" y="' + (y + 4).toFixed(1) + '" text-anchor="end" fill="' + textMuted + '" font-family="system-ui,-apple-system,sans-serif" font-size="11" font-weight="600">' +
        escapeXml(formatNumber(t, cfg.unit)) + '</text>'
      );
    });

    var nCats = cfg.categories.length;
    var zeroRatio = (0 - niceMin) / (niceMax - niceMin);
    var zeroY = plotTop + plotH * (1 - Math.max(0, Math.min(1, zeroRatio)));

    if (cfg.type === "bar") {
      var slotW = plotW / nCats;
      var nSeries = cfg.series.length;
      var groupW = Math.min(slotW * 0.72, 76);
      var barW = Math.max(8, (groupW - (nSeries - 1) * 4) / nSeries);

      for (var cIdx = 0; cIdx < nCats; cIdx++) {
        var groupStart = leftPad + cIdx * slotW + (slotW - (barW * nSeries + (nSeries - 1) * 4)) / 2;
        for (var sIdx = 0; sIdx < nSeries; sIdx++) {
          var val = Number(cfg.series[sIdx].data[cIdx]) || 0;
          var valRatio = (val - niceMin) / (niceMax - niceMin);
          var valY = plotTop + plotH * (1 - valRatio);
          var barTop = Math.min(valY, zeroY);
          var barH = Math.max(3, Math.abs(zeroY - valY));
          var bx = groupStart + sIdx * (barW + 4);
          var color = cfg.palette[sIdx % cfg.palette.length];
          var bgid = this.uid + "_bargrad_" + (sIdx % cfg.palette.length);
          var valText = formatNumber(val, cfg.unit);

          svgParts.push(
            '<rect class="apex-data-point" ' +
            'data-series="' + escapeXml(cfg.series[sIdx].name) + '" ' +
            'data-cat="' + escapeXml(cfg.categories[cIdx]) + '" ' +
            'data-val="' + escapeXml(valText) + '" ' +
            'data-color="' + escapeXml(color) + '" ' +
            'x="' + bx.toFixed(1) + '" y="' + barTop.toFixed(1) + '" ' +
            'width="' + barW.toFixed(1) + '" height="' + barH.toFixed(1) + '" ' +
            'rx="' + Math.min(6, barW / 2).toFixed(1) + '" fill="url(#' + bgid + ')" style="cursor:pointer;transition:opacity 0.15s;"/>'
          );

          // Value label cleanly ABOVE bar (never colliding with bar or X-axis label)
          if (nSeries === 1 && nCats <= 10) {
            var labelY = Math.max(plotTop - 4, barTop - 7);
            svgParts.push(
              '<text x="' + (bx + barW / 2).toFixed(1) + '" y="' + labelY.toFixed(1) + '" text-anchor="middle" fill="' + textPrimary + '" font-family="system-ui,-apple-system,sans-serif" font-size="10.5" font-weight="700">' +
              escapeXml(valText) + '</text>'
            );
          }
        }
      }
    } else {
      // Line / Area / Scatter
      cfg.series.forEach(function (s, sIdx) {
        var col = cfg.palette[sIdx % cfg.palette.length];
        var gid = this.uid + "_grad_" + (sIdx % cfg.palette.length);
        var pts = [];
        for (var i = 0; i < nCats; i++) {
          var v = Number(s.data[i]) || 0;
          var px = nCats === 1 ? (leftPad + plotW / 2) : (leftPad + (i / (nCats - 1)) * plotW);
          var py = plotTop + plotH * (1 - (v - niceMin) / (niceMax - niceMin));
          pts.push({ x: px, y: py, val: v, cat: cfg.categories[i] });
        }

        if (cfg.type !== "scatter" && pts.length > 1) {
          var linePath = buildSmoothPath(pts);
          if (cfg.type === "area") {
            var areaPath = linePath +
              " L " + pts[pts.length - 1].x.toFixed(1) + " " + zeroY.toFixed(1) +
              " L " + pts[0].x.toFixed(1) + " " + zeroY.toFixed(1) + " Z";
            svgParts.push('<path d="' + areaPath + '" fill="url(#' + gid + ')"/>');
          }
          svgParts.push(
            '<path d="' + linePath + '" fill="none" stroke="' + escapeXml(col) + '" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>'
          );
        }

        pts.forEach(function (pt) {
          var valFormatted = formatNumber(pt.val, cfg.unit);
          svgParts.push(
            '<circle class="apex-data-point" ' +
            'data-series="' + escapeXml(s.name) + '" ' +
            'data-cat="' + escapeXml(pt.cat) + '" ' +
            'data-val="' + escapeXml(valFormatted) + '" ' +
            'data-color="' + escapeXml(col) + '" ' +
            'cx="' + pt.x.toFixed(1) + '" cy="' + pt.y.toFixed(1) + '" r="5" ' +
            'fill="' + cardBg + '" stroke="' + escapeXml(col) + '" stroke-width="2.6" style="cursor:pointer;"/>'
          );
        });
      }, this);
    }

    // X-axis categories
    for (var i = 0; i < nCats; i++) {
      var cx = cfg.type === "bar"
        ? (leftPad + (i + 0.5) * (plotW / nCats))
        : (nCats === 1 ? leftPad + plotW / 2 : leftPad + (i / (nCats - 1)) * plotW);
      var cy = plotTop + plotH + 18;
      var rawCat = String(cfg.categories[i]);
      var cleanCat = rawCat.length > 16 ? rawCat.substring(0, 15) + "…" : rawCat;
      if (rotateX) {
        svgParts.push(
          '<text x="' + cx.toFixed(1) + '" y="' + cy.toFixed(1) + '" text-anchor="end" transform="rotate(-32 ' + cx.toFixed(1) + ' ' + cy.toFixed(1) + ')" fill="' + textMuted + '" font-family="system-ui,-apple-system,sans-serif" font-size="11" font-weight="600">' +
          escapeXml(cleanCat) + '</text>'
        );
      } else {
        svgParts.push(
          '<text x="' + cx.toFixed(1) + '" y="' + cy.toFixed(1) + '" text-anchor="middle" fill="' + textMuted + '" font-family="system-ui,-apple-system,sans-serif" font-size="11" font-weight="600">' +
          escapeXml(cleanCat) + '</text>'
        );
      }
    }

    // Legend
    if (hasLegend) {
      var legY = H - 10;
      var spacing = Math.min(130, (W - 40) / cfg.series.length);
      var startX = (W - spacing * cfg.series.length) / 2 + 12;
      cfg.series.forEach(function (s, idx) {
        var lx = startX + idx * spacing;
        var col = cfg.palette[idx % cfg.palette.length];
        svgParts.push(
          '<circle cx="' + lx.toFixed(1) + '" cy="' + (legY - 4) + '" r="5" fill="' + escapeXml(col) + '"/>' +
          '<text x="' + (lx + 10).toFixed(1) + '" y="' + legY + '" fill="' + textPrimary + '" font-family="system-ui,-apple-system,sans-serif" font-size="11.5" font-weight="600">' +
          escapeXml(String(s.name).substring(0, 16)) + '</text>'
        );
      });
    }
  };

  ApexCharts.prototype._drawPieDonut = function (cfg, svgParts, W, H, topStart, textPrimary, textMuted, cardBg) {
    var values = cfg.series[0].data.map(function (v) { return Math.max(0, Number(v) || 0); });
    var total = values.reduce(function (a, b) { return a + b; }, 0);
    if (total <= 0) total = 1;

    var cx = W * 0.36;
    var cy = topStart + (H - topStart) * 0.5;
    var rOuter = Math.min(W * 0.25, (H - topStart) * 0.39);
    var rInner = cfg.type === "donut" || cfg.type === "radialbar" ? rOuter * 0.58 : 0;

    var startAngle = -Math.PI / 2;
    values.forEach(function (val, i) {
      var sliceAngle = (val / total) * Math.PI * 2;
      var endAngle = startAngle + sliceAngle;
      var col = cfg.palette[i % cfg.palette.length];
      var pct = ((val / total) * 100).toFixed(1) + "%";
      var catName = cfg.categories[i] || ("Slice " + (i + 1));

      if (sliceAngle >= Math.PI * 1.999) {
        svgParts.push(
          '<circle class="apex-data-point" data-series="' + escapeXml(catName) + '" data-cat="' + escapeXml(pct) + '" data-val="' + escapeXml(formatNumber(val, cfg.unit)) + '" data-color="' + escapeXml(col) + '" cx="' + cx + '" cy="' + cy + '" r="' + rOuter + '" fill="' + escapeXml(col) + '"/>'
        );
        if (rInner > 0) {
          svgParts.push('<circle cx="' + cx + '" cy="' + cy + '" r="' + rInner + '" fill="' + cardBg + '"/>');
        }
      } else if (sliceAngle > 0.001) {
        var x1 = cx + rOuter * Math.cos(startAngle);
        var y1 = cy + rOuter * Math.sin(startAngle);
        var x2 = cx + rOuter * Math.cos(endAngle);
        var y2 = cy + rOuter * Math.sin(endAngle);
        var largeArc = sliceAngle > Math.PI ? 1 : 0;
        var d;
        if (rInner > 0) {
          var ix1 = cx + rInner * Math.cos(endAngle);
          var iy1 = cy + rInner * Math.sin(endAngle);
          var ix2 = cx + rInner * Math.cos(startAngle);
          var iy2 = cy + rInner * Math.sin(startAngle);
          d = [
            "M", x1.toFixed(2), y1.toFixed(2),
            "A", rOuter.toFixed(2), rOuter.toFixed(2), 0, largeArc, 1, x2.toFixed(2), y2.toFixed(2),
            "L", ix1.toFixed(2), iy1.toFixed(2),
            "A", rInner.toFixed(2), rInner.toFixed(2), 0, largeArc, 0, ix2.toFixed(2), iy2.toFixed(2),
            "Z"
          ].join(" ");
        } else {
          d = [
            "M", cx.toFixed(2), cy.toFixed(2),
            "L", x1.toFixed(2), y1.toFixed(2),
            "A", rOuter.toFixed(2), rOuter.toFixed(2), 0, largeArc, 1, x2.toFixed(2), y2.toFixed(2),
            "Z"
          ].join(" ");
        }
        svgParts.push(
          '<path class="apex-data-point" data-series="' + escapeXml(catName) + '" data-cat="' + escapeXml(pct) + '" data-val="' + escapeXml(formatNumber(val, cfg.unit)) + '" data-color="' + escapeXml(col) + '" d="' + d + '" fill="' + escapeXml(col) + '" stroke="' + cardBg + '" stroke-width="2" style="cursor:pointer;"/>'
        );
      }
      startAngle = endAngle;
    });

    if (rInner > 0) {
      svgParts.push(
        '<text x="' + cx.toFixed(1) + '" y="' + (cy - 4).toFixed(1) + '" text-anchor="middle" fill="' + textMuted + '" font-family="system-ui,-apple-system,sans-serif" font-size="11" font-weight="600">TOTAL</text>' +
        '<text x="' + cx.toFixed(1) + '" y="' + (cy + 16).toFixed(1) + '" text-anchor="middle" fill="' + textPrimary + '" font-family="system-ui,-apple-system,sans-serif" font-size="16" font-weight="800">' + escapeXml(formatNumber(total, cfg.unit)) + '</text>'
      );
    }

    // Right-side clean legend with percentages
    var legX = W * 0.66;
    var rowH = 26;
    var legStartY = Math.max(topStart + 24, cy - (values.length * rowH) / 2 + 10);
    values.forEach(function (val, i) {
      var ly = legStartY + i * rowH;
      if (ly > H - 12) return;
      var col = cfg.palette[i % cfg.palette.length];
      var pct = ((val / total) * 100).toFixed(1) + "%";
      var lbl = String(cfg.categories[i] || ("Item " + (i + 1)));
      if (lbl.length > 18) lbl = lbl.substring(0, 17) + "…";
      svgParts.push(
        '<rect x="' + legX.toFixed(1) + '" y="' + (ly - 10).toFixed(1) + '" width="12" height="12" rx="3" fill="' + escapeXml(col) + '"/>' +
        '<text x="' + (legX + 18).toFixed(1) + '" y="' + ly.toFixed(1) + '" fill="' + textPrimary + '" font-family="system-ui,-apple-system,sans-serif" font-size="12" font-weight="600">' + escapeXml(lbl) + '</text>' +
        '<text x="' + (W - 20) + '" y="' + ly.toFixed(1) + '" text-anchor="end" fill="' + textMuted + '" font-family="system-ui,-apple-system,sans-serif" font-size="11.5" font-weight="700">' + escapeXml(pct) + '</text>'
      );
    });
  };

  ApexCharts.prototype._drawRadar = function (cfg, svgParts, W, H, topStart, textPrimary, textMuted, gridColor) {
    var n = cfg.categories.length;
    var cx = W / 2;
    var cy = topStart + (H - topStart) / 2;
    var radius = Math.min(W, H - topStart) * 0.34;
    var allVals = [];
    cfg.series.forEach(function (s) { s.data.forEach(function (v) { allVals.push(Number(v) || 0); }); });
    var maxV = Math.max.apply(null, allVals.concat([10]));

    [0.25, 0.5, 0.75, 1].forEach(function (rFrac) {
      var ringPts = [];
      for (var i = 0; i < n; i++) {
        var ang = -Math.PI / 2 + (i * 2 * Math.PI) / n;
        ringPts.push((cx + radius * rFrac * Math.cos(ang)).toFixed(1) + "," + (cy + radius * rFrac * Math.sin(ang)).toFixed(1));
      }
      svgParts.push('<polygon points="' + ringPts.join(" ") + '" fill="none" stroke="' + gridColor + '" stroke-width="1"/>');
    });

    for (var i = 0; i < n; i++) {
      var ang = -Math.PI / 2 + (i * 2 * Math.PI) / n;
      var lx = cx + (radius + 22) * Math.cos(ang);
      var ly = cy + (radius + 18) * Math.sin(ang);
      svgParts.push(
        '<line x1="' + cx + '" y1="' + cy + '" x2="' + (cx + radius * Math.cos(ang)).toFixed(1) + '" y2="' + (cy + radius * Math.sin(ang)).toFixed(1) + '" stroke="' + gridColor + '"/>' +
        '<text x="' + lx.toFixed(1) + '" y="' + (ly + 4).toFixed(1) + '" text-anchor="middle" fill="' + textMuted + '" font-family="system-ui,-apple-system,sans-serif" font-size="11" font-weight="600">' +
        escapeXml(String(cfg.categories[i]).substring(0, 14)) + '</text>'
      );
    }

    cfg.series.forEach(function (s, sIdx) {
      var col = cfg.palette[sIdx % cfg.palette.length];
      var poly = [];
      for (var i = 0; i < n; i++) {
        var v = Math.max(0, Number(s.data[i]) || 0);
        var frac = Math.min(1, v / maxV);
        var ang = -Math.PI / 2 + (i * 2 * Math.PI) / n;
        var px = cx + radius * frac * Math.cos(ang);
        var py = cy + radius * frac * Math.sin(ang);
        poly.push(px.toFixed(1) + "," + py.toFixed(1));
      }
      svgParts.push(
        '<polygon points="' + poly.join(" ") + '" fill="' + escapeXml(col) + '" fill-opacity="0.22" stroke="' + escapeXml(col) + '" stroke-width="2.5"/>'
      );
    });
  };

  ApexCharts.prototype._bindInteractions = function () {
    if (!this.el) return;
    var tooltip = this.el.querySelector(".apex-tooltip");
    if (!tooltip) return;
    var container = this.el.querySelector(".apexcharts-canvas");
    var pts = this.el.querySelectorAll(".apex-data-point");
    pts.forEach(function (pt) {
      function showTip(evt) {
        var sName = pt.getAttribute("data-series") || "";
        var cat = pt.getAttribute("data-cat") || "";
        var val = pt.getAttribute("data-val") || "";
        var col = pt.getAttribute("data-color") || "#EA580C";
        tooltip.innerHTML =
          '<div style="display:flex;align-items:center;gap:6px;margin-bottom:2px;">' +
            '<span style="width:8px;height:8px;border-radius:50%;background:' + col + ';display:inline-block;"></span>' +
            '<strong style="font-size:11.5px;">' + escapeXml(cat) + '</strong>' +
          '</div>' +
          '<div style="font-size:12px;opacity:0.92;">' + escapeXml(sName) + ': <strong>' + escapeXml(val) + '</strong></div>';
        var rect = container.getBoundingClientRect();
        var clientX = (evt.touches && evt.touches[0] ? evt.touches[0].clientX : evt.clientX) || rect.left + rect.width / 2;
        var clientY = (evt.touches && evt.touches[0] ? evt.touches[0].clientY : evt.clientY) || rect.top + 40;
        var left = Math.max(8, Math.min(rect.width - 150, clientX - rect.left - 50));
        var top = Math.max(8, clientY - rect.top - 58);
        tooltip.style.left = left + "px";
        tooltip.style.top = top + "px";
        tooltip.style.opacity = "1";
      }
      pt.addEventListener("mouseenter", showTip);
      pt.addEventListener("touchstart", showTip, { passive: true });
      pt.addEventListener("mouseleave", function () { tooltip.style.opacity = "0"; });
    });
  };

  global.ApexCharts = ApexCharts;
})(typeof window !== "undefined" ? window : this);
